package com.example.restaurant.controller;
import com.example.restaurant.dto.AdminDashboardResponse; import com.example.restaurant.service.AdminDashboardService; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/admin/dashboard") @PreAuthorize("hasRole('ADMIN')") @SecurityRequirement(name="basicAuth") @Tag(name="Admin Dashboard")
public class AdminDashboardController {private final AdminDashboardService service; public AdminDashboardController(AdminDashboardService service){this.service=service;} @GetMapping public AdminDashboardResponse dashboard(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return service.dashboard(date==null?LocalDate.now():date);}}
